#!/bin/bash
# Evaluate GenEval images generated by the umm_uniquery cc12m checkpoint
# (infer/generate_geneval_umm.py) with the shared GenEval harness.
#
# Same detector/config as the Janus run, but a SEPARATE images/results dir so
# Janus's own results are untouched.
#
# Usage:
#   bash scripts/run_geneval_umm_eval.sh [--gpu N]     # default GPU 1
set -e

GENEVAL_ENV=/home/mingjun/.conda/envs/geneval/bin/python
GENEVAL=/home/mingjun/geneval
HERE=/home/mingjun/umm_uniquery
IMGDIR="$HERE/outputs/geneval_cc12m/images"
RES="$HERE/outputs/geneval_cc12m/results.jsonl"
DETECTOR=/home/mingjun/Janus/janus_eval_GEval/detector
CONFIG=/home/mingjun/mmdetection/configs/mask2former/mask2former_swin-s-p4-w7-224_lsj_8x2_50e_coco.py
GPU=1

for a in "$@"; do
  case "$a" in
    --gpu) GPU="$2" ;;
    --gpu=*) GPU="${a#--gpu=}" ;;
  esac
done

mkdir -p "$HERE/outputs/geneval_cc12m"

echo "== evaluating $IMGDIR (GPU $GPU) =="
CUDA_VISIBLE_DEVICES=$GPU "$GENEVAL_ENV" -W ignore \
  "$GENEVAL/evaluation/evaluate_images.py" "$IMGDIR" \
  --outfile "$RES" \
  --model-path "$DETECTOR" \
  --model-config "$CONFIG" \
  2>&1 | tee "$HERE/outputs/geneval_cc12m/evaluate.log"

echo "== summary =="
"$GENEVAL_ENV" "$GENEVAL/evaluation/summary_scores.py" "$RES" 2>/dev/null \
  | tee "$HERE/outputs/geneval_cc12m/summary.log"
